package org.usbworkbench;
import java.io.*;import android.content.*;import android.content.pm.*;import java.util.*;
public final class FilesystemToolsTest{
 static int checks;static void yes(boolean b){if(!b)throw new AssertionError();checks++;}
 public static void main(String[] args)throws Exception{
 File dir=new File("artifacts/native-fixtures/fs-tools");dir.mkdirs();Context c=new Context(){final ApplicationInfo info=new ApplicationInfo();{info.nativeLibraryDir=new File("app/src/main/jniLibs/arm64-v8a").getAbsolutePath();}public ApplicationInfo getApplicationInfo(){return info;}public File getFilesDir(){return dir;}};
 for(String layout:new String[]{"mbr","gpt"})for(String fs:new String[]{"fat12","fat16","fat32","exfat","ntfs","ext2","ext4","f2fs"}){File file=new File(dir,"owned-"+layout+"-"+fs+".img");try(NativeIntegrationTest.Image disk=new NativeIntegrationTest.Image(file,(fs.equals("f2fs")?256L:fs.equals("fat12")?16L:(fs.equals("fat32")||fs.equals("exfat"))?128L:64L)*1048576)){if(NativeFormat.supports(fs))NativeFormat.format(c,disk,fs,layout,"OWNED",0,(a,b)->{},()->false);else AdvancedDiskTools.format(disk,fs,layout,"OWNED",0,(a,b)->{});byte[] table=new byte[34*512],tail=new byte[33*512];disk.read(0,table,table.length);disk.read(disk.blockCount()-33,tail,tail.length);FilesystemTools.Volume volume=FilesystemTools.select(disk,1,false);yes(volume.kind.equals(fs.startsWith("ext")?"ext":fs.startsWith("fat")?"fat":fs));yes(FilesystemTools.select(volume.disk,0,false).kind.equals(volume.kind));int before=disk.writes;yes(FilesystemTools.run(c,volume,false,(a,b)->{},()->false,x->{}).startsWith("FS_CHECK_OK"));yes(disk.writes==before);
 if(fs.equals("fat32")){byte[] b=new byte[512];volume.disk.read(1,b,512);DiskTools.le32(b,488,0);volume.disk.write(1,b,512);}
 if(fs.equals("exfat")){byte[] b=new byte[512];volume.disk.read(11,b,512);b[0]^=1;volume.disk.write(11,b,512);}
 if(fs.equals("fat32")||fs.equals("exfat")){int unchanged=disk.writes;try{FilesystemTools.run(c,volume,false,(a,b)->{},()->false,x->{});throw new AssertionError("Corruption not reported");}catch(IOException e){yes(e.getMessage().startsWith("FS_CHECK_ISSUES"));yes(disk.writes==unchanged);}}
 if(fs.equals("ext2")){byte[] b=new byte[512];volume.disk.read(2,b,512);DiskTools.le32(b,12,0);volume.disk.write(2,b,512);}
 if(fs.equals("f2fs")){byte[] b=new byte[512];volume.disk.read(2,b,512);b[0]^=1;volume.disk.write(2,b,512);volume=FilesystemTools.select(disk,1,true);}
 if(fs.equals("exfat")){try{FilesystemTools.run(c,volume,true,(a,b)->{},()->false,x->{});throw new AssertionError("Severe exFAT damage should be refused by automatic mode");}catch(IOException e){yes(e.getMessage().startsWith("FS_REPAIR_ISSUES"));}byte[] b=new byte[512];volume.disk.read(11,b,512);b[0]^=1;volume.disk.write(11,b,512);}
 yes(FilesystemTools.run(c,volume,true,(a,b)->{},()->false,x->{}).startsWith("FS_REPAIR_OK"));if(fs.equals("f2fs")){F2fsInspector.inspect(volume.disk);yes(true);}before=disk.writes;FilesystemTools.run(c,volume,false,(a,b)->{},()->false,x->{});yes(disk.writes==before);byte[] after=new byte[table.length],afterTail=new byte[tail.length];disk.read(0,after,after.length);disk.read(disk.blockCount()-33,afterTail,afterTail.length);yes(Arrays.equals(table,after)&&Arrays.equals(tail,afterTail));try{FilesystemTools.select(disk,0,true);throw new AssertionError();}catch(IOException e){yes(e.getMessage().equals("FS_RAW_TABLE"));}if(layout.equals("mbr")&&fs.equals("fat12")){byte[] chunk=new byte[16384];for(long at=0;at<volume.sectors;){int n=(int)Math.min(32,volume.sectors-at);disk.read(2048+at,chunk,n*512);disk.write(63+at,chunk,n*512);at+=n;}byte[] mbr=new byte[512];disk.read(0,mbr,512);DiskTools.le32(mbr,454,63);disk.write(0,mbr,512);FilesystemTools.Volume legacy=FilesystemTools.select(disk,1,true);yes(legacy.start==63);int unchanged=disk.writes;FilesystemTools.run(c,legacy,false,(a,b)->{},()->false,x->{});yes(disk.writes==unchanged);mbr[466]=1;DiskTools.le32(mbr,470,64);DiskTools.le32(mbr,474,128);disk.write(0,mbr,512);unchanged=disk.writes;try{FilesystemTools.select(disk,1,true);throw new AssertionError("Overlap accepted");}catch(IOException e){yes(e.getMessage().equals("FS_PARTITION")&&disk.writes==unchanged);}}
 System.out.println("PASS filesystem check/limitedrepair/tablepreservation "+layout+" "+fs);
 }finally{file.delete();}}
 File f=new File(dir,"invalid.img");try(NativeIntegrationTest.Image disk=new NativeIntegrationTest.Image(f,64L*1048576)){try{FilesystemTools.select(disk,1,true);throw new AssertionError();}catch(IOException e){yes(disk.writes==0);}}finally{f.delete();}
 System.out.println("PASS: "+checks+" actual FAT/exFAT/NTFS/ext/F2FS check/read-only guard, limited repairs, damagedmetadata recovery and table preservation assertions");
 }
}
